const D={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const won=s=>s.r===2&&s.c===2;
const pos=(r,c,y)=>[(c-1)*1.1,y,(1-r)*1.1];
export function initialState(){return {r:0,c:0,moves:0,hint:false,msg:"Reach the orange goal square."};}
export function reduce({state,event}){
 if(event.type!=="action")return state;
 const s={...state};
 if(won(s)){s.msg="Already won! Press Reset to play again.";return s;}
 if(event.action==="hint"){s.hint=true;s.msg="Follow the green arrow.";return s;}
 const d=D[event.action];if(!d)return state;
 const r=s.r+d[0],c=s.c+d[1];
 if(r<0||r>2||c<0||c>2){s.msg="That move would leave the board.";return s;}
 s.r=r;s.c=c;s.moves++;s.hint=false;
 s.msg=won(s)?("You reached the goal in "+s.moves+" moves (shortest is 4)."):"Moved "+event.action+".";
 return s;
}
export function evaluate({state}){
 const s=state||initialState();
 const w=won(s);
 const dist=(2-s.r)+(2-s.c);
 const ty=w?0.43:0.35;
 const nodes={token:{position:pos(s.r,s.c,ty)}};
 const show=s.hint&&!w;
 let q=[0,0,-0.7071068,0.7071068];
 if(2-s.r>=2-s.c)q=[-0.7071068,0,0,0.7071068];
 nodes.hintArrow={visible:show,position:pos(s.r,s.c,0.75),quaternion:q};
 return {nodes,readouts:{moves:s.moves,dist},goal:{status:w?"won":"playing",message:s.msg}};
}
